package com.yue.admin;
import com.yue.entity.User; import com.yue.repository.SceneRepository; import com.yue.repository.UserRepository; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/admin") public class AdminController { private final AdminAuthService auth; private final UserRepository users; private final SceneRepository scenes; public AdminController(AdminAuthService a,UserRepository u,SceneRepository s){auth=a;users=u;scenes=s;} @PostMapping("/auth/login") public AdminLoginResponse login(@RequestBody AdminLoginRequest r){return auth.login(r.username(),r.password());} @GetMapping("/dashboard") public Map<String,Object> dashboard(){return Map.of("users",users.count(),"scenes",scenes.count());} @GetMapping("/users") public Map<String,Object> list(){return Map.of("items",users.findAll().stream().map(this::safe).toList());} private Map<String,Object> safe(User u){return Map.of("id",u.getId(),"username",u.getUsername(),"nickname",u.getNickname()==null?"":u.getNickname(),"phone",mask(u.getPhone()));} private String mask(String s){return s==null||s.length()<7?s:s.substring(0,3)+"****"+s.substring(s.length()-4);} }
